CALL {
  MATCH (ch:CrowdHour {camera_location: 'DemoBooth_NVIDIA'})
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN ch.hour_utc AS hour, ch.avg_hc AS average_head_count, ch.peak_hc AS peak_head_count, ch.event_count AS event_count
}
RETURN hour, average_head_count, peak_head_count, event_count ORDER BY hour
